A kért projekt két fájlból áll: egy minimalista Flask alapú main.py backendből és egy index.html front-endből, fekete, Apple-szerű UI/UX, finom animációkkal, JSON feltöltéssel/megtekintéssel, és integrált GPT-OSS-120B összefoglaló + chat funkcióval a Cerebras Cloud SDK-n keresztül. [1]

## Fő funkciók
- Fekete háttér, “apple.com” stílusú tipográfia, elegáns rács és mikro-animációk CSS-ben, prefers-reduced-motion tiszteletben tartása. [2]
- JSON feltöltés, kliens oldali validálás, szerver oldali parsolás, szépített megjelenítés. [2]
- GPT-OSS-120B hívás streameléssel, automatikus összefoglaló a feltöltött JSON-ról, és chat mód felhasználói kérdésekkel. [1][3][4]
- SSE alapú stream kezelés frontenden a tokenenkénti kijelzéshez. [1]

## Előfeltételek
- Python 3.10+ és pip, Flask telepítés: pip install flask cerebras-cloud-sdk. [1]
- Környezeti változó: CEREBRAS_API_KEY beállítása a Cerebras Cloud SDK-hoz. [1]
- A modellnév: "gpt-oss-120b" a kért integráció szerint; a Cerebras Chat Completions API kompatibilis a megadott streaming mintával. [1][3]

## main.py
```python
import os
import json
from flask import Flask, request, send_from_directory, Response, jsonify
from werkzeug.utils import secure_filename
from cerebras.cloud.sdk import Cerebras

app = Flask(__name__, static_folder=".", static_url_path="")
app.config["MAX_CONTENT_LENGTH"] = 10 * 1024 * 1024  # 10MB
app.config["UPLOAD_FOLDER"] = "uploads"
os.makedirs(app.config["UPLOAD_FOLDER"], exist_ok=True)

# Cerebras kliens
client = Cerebras(api_key=os.environ.get("CEREBRAS_API_KEY"))

# Statikus index kiszolgálás
@app.route("/")
def index():
    return send_from_directory(".", "index.html")

# JSON feltöltés és preview adat visszaadása
@app.route("/upload-json", methods=["POST"])
def upload_json():
    if "file" not in request.files:
        return jsonify({"error": "Nincs file part"}), 400
    f = request.files["file"]
    if f.filename == "":
        return jsonify({"error": "Nincs kiválasztott fájl"}), 400
    filename = secure_filename(f.filename)
    path = os.path.join(app.config["UPLOAD_FOLDER"], filename)
    try:
        raw = f.read().decode("utf-8", errors="replace")
        parsed = json.loads(raw)
    except Exception as e:
        return jsonify({"error": f"Hibás JSON: {str(e)}"}), 400
    with open(path, "w", encoding="utf-8") as out:
        json.dump(parsed, out, ensure_ascii=False, indent=2)
    return jsonify({
        "filename": filename,
        "pretty": json.dumps(parsed, ensure_ascii=False, indent=2),
        "size": len(raw)
    }), 200

# SSE stream összefoglaló generálás a feltöltött JSON-hoz
@app.route("/summarize-stream", methods=["POST"])
def summarize_stream():
    data = request.get_json(force=True)
    pretty_json = data.get("pretty", "")
    system_prompt = (
        "Te egy szakértő összefoglaló készítő vagy. "
        "Kapni fogsz egy JSON tartalmat. "
        "Feladat: tömör, strukturált, pontokba szedett összefoglaló magyarul. "
        "Emeld ki a fő kulcsokat, hierarchiát, rendellenességeket és fontos számokat."
    )
    user_prompt = f"Ez a JSON:\n``````"

    def generate():
        stream = client.chat.completions.create(
            messages=[
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt},
            ],
            model="gpt-oss-120b",
            stream=True,
            max_completion_tokens=4096,
            temperature=0.2,
            top_p=0.9,
            reasoning_effort="medium",
        )
        for chunk in stream:
            delta = getattr(chunk.choices.delta, "content", "") or ""
            yield f"data: {delta}\n\n"
        yield "event: done\ndata: [DONE]\n\n"

    return Response(generate(), mimetype="text/event-stream")

# SSE stream chat
@app.route("/chat-stream", methods=["POST"])
def chat_stream():
    data = request.get_json(force=True)
    history = data.get("messages", [])
    if not isinstance(history, list):
        return jsonify({"error": "messages list szükséges"}), 400

    def generate():
        stream = client.chat.completions.create(
            messages=history,
            model="gpt-oss-120b",
            stream=True,
            max_completion_tokens=4096,
            temperature=0.7,
            top_p=0.9,
            reasoning_effort="medium",
        )
        for chunk in stream:
            delta = getattr(chunk.choices.delta, "content", "") or ""
            yield f"data: {delta}\n\n"
        yield "event: done\ndata: [DONE]\n\n"

    return Response(generate(), mimetype="text/event-stream")

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5173, debug=True)
```


