        <header><h3>Automatikus összefoglaló</h3></header>
        <div class="body">
          <div class="controls">
            <button id="summarizeBtn" class="accent">Összefoglaló indítása</button>
            <span class="badge" id="sumBadge">Készenlét</span>
          </div>
