          <div id="chatWindow" class="chat"></div>
          <div class="controls">
            <input id="chatInput" placeholder="Kérdés írása…" />
            <button id="sendBtn" class="accent">Küldés</button>
            <span class="badge" id="chatBadge">Chat készen</span>
          </div>
        </div>
      </section>
