  <script>
    const drop = document.getElementById('drop');
    const fileInput = document.getElementById('file');
    const uploadBtn = document.getElementById('uploadBtn');
    const statusEl = document.getElementById('status');
    const preview = document.getElementById('preview');

    const summarizeBtn = document.getElementById('summarizeBtn');
    const sumBadge = document.getElementById('sumBadge');
    const summaryEl = document.getElementById('summary');

    const chatWindow = document.getElementById('chatWindow');
    const chatInput = document.getElementById('chatInput');
    const sendBtn = document.getElementById('sendBtn');
    const chatBadge = document.getElementById('chatBadge');

    let lastPretty = "";
    let messages = [{ role: "system", content: "Légy tömör, hasznos és pontos magyar válaszokat adj." }];

    // Drag & drop
    ;['dragenter','dragover'].forEach(ev => drop.addEventListener(ev, e => {
      e.preventDefault(); e.stopPropagation(); drop.classList.add('drag');
    }));
    ;['dragleave','drop'].forEach(ev => drop.addEventListener(ev, e => {
      e.preventDefault(); e.stopPropagation(); drop.classList.remove('drag');
    }));
    drop.addEventListener('drop', e => {
      const f = e.dataTransfer.files?.;
      if (f) fileInput.files = e.dataTransfer.files;
    });

    // Upload
    uploadBtn.addEventListener('click', async () => {
      const f = fileInput.files?.;
      if (!f) { statusEl.textContent = "Nincs fájl kiválasztva"; return; }
      const fd = new FormData();
      fd.append('file', f);
      statusEl.textContent = "Feltöltés…";
      try {
        const res = await fetch('/upload-json', { method: 'POST', body: fd });
        const data = await res.json();
        if (!res.ok) throw new Error(data.error || 'Ismeretlen hiba');
        lastPretty = data.pretty;
        statusEl.textContent = `Feltöltve: ${data.filename} (${data.size} bájt)`;
        preview.textContent = data.pretty;
      } catch (e) {
        statusEl.textContent = `Hiba: ${e.message}`;
      }
    });

    // SSE helper
    async function ssePost(url, body, onChunk, onDone, onError) {
      const res = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body)
      });
      if (!res.ok || !res.body) throw new Error("Hálózati hiba");
      const reader = res.body.getReader();
      const decoder = new TextDecoder("utf-8");
      let buffer = "";
      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const parts = buffer.split("\n\n");
        buffer = parts.pop() || "";
        for (const p of parts) {
          if (p.startsWith("event: done")) { onDone && onDone(); return; }
          const line = p.split("data: ").pop();
          if (line && onChunk) onChunk(line);
        }
      }
      onDone && onDone();
    }

    // Summarize stream
    summarizeBtn.addEventListener('click', async () => {
      if (!lastPretty) { sumBadge.textContent = "Nincs JSON"; sumBadge.className = "badge err"; return; }
      summaryEl.textContent = "";
      sumBadge.textContent = "Fut…"; sumBadge.className = "badge";
      try {
        await ssePost("/summarize-stream", { pretty: lastPretty },
          (chunk) => { summaryEl.textContent += chunk; },
          () => { sumBadge.textContent = "Kész"; sumBadge.className = "badge ok"; },
          (err) => { sumBadge.textContent = "Hiba"; sumBadge.className = "badge err"; }
        );
      } catch (e) {
        sumBadge.textContent = "Hiba"; sumBadge.className = "badge err";
      }
    });

    // Chat UI
    function renderMessage(role, content) {
      const wrap = document.createElement('div');
      wrap.className = 'msg';
      const r = document.createElement('div');
      r.className = 'role';
      r.textContent = role === 'user' ? 'Felhasználó' : 'Asszisztens';
      const c = document.createElement('div');
      c.textContent = content;
      wrap.appendChild(r); wrap.appendChild(c);
      chatWindow.appendChild(wrap);
      chatWindow.scrollTop = chatWindow.scrollHeight;
    }

    async function sendMessage() {
      const txt = chatInput.value.trim();
      if (!txt) return;
      chatInput.value = "";
      messages.push({ role: "user", content: txt });
      renderMessage("user", txt);

      const acc = { text: "" };
      renderMessage("assistant", "");
      const lastAssistant = chatWindow.lastChild.querySelector(':scope > div:nth-child(2)');

      chatBadge.textContent = "Válasz folyamatban…"; chatBadge.className = "badge";
      try {
        await ssePost("/chat-stream", { messages },
          (chunk) => { acc.text += chunk; lastAssistant.textContent = acc.text; },
          () => { 
            chatBadge.textContent = "Chat készen"; chatBadge.className = "badge ok";
            messages.push({ role: "assistant", content: acc.text });
          },
          (err) => { chatBadge.textContent = "Hiba"; chatBadge.className = "badge err"; }
        );
      } catch (e) {
        chatBadge.textContent = "Hiba"; chatBadge.className = "badge err";
      }
    }

    sendBtn.addEventListener('click', sendMessage);
    chatInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendMessage(); }
    });

    // Dark mód figyelése (ha szeretnénk reagálni OS szintű váltásra)
    const mq = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)');
    if (mq && mq.addEventListener) {
      mq.addEventListener('change', () => {
        // Tartalék hook; jelenleg fix dark theme
      });
    }
  </script>
</body>
